   * 刷新容器内容
   */
  @Require
  @BuilderParam
  content: CustomBuilder;

  /**
   * 渲染刷新布局
   * @returns {void} 无返回值
   */
  build() {
    IBestPullRefresh({
      loading: this.loading,
      scroller: this.scroller,
      isEnableSlideUp: this.isEnableSlideUp,
      defaultContent: (): void => {
        if (this.content) {
          this.content();
        }
      },
      onRefresh: (direction: "pull" | "slideUp"): void => this.onRefresh(direction)
    });
  }
}

